import { readFileSync } from 'node:fs'

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }
const isWs = (c) => c === ' ' || c === '\t'
const isNameCh = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const newTable = () => ({ type: 'table', map: new Map(), header: false })

function cmp(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
  atEnd() { return this.c === undefined || this.c === '#' || this.c === ';' }

  basic() {
    this.i++
    let out = ''
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      const e = this.c
      if (e === undefined) fail('unterminated string')
      const cp = String.fromCodePoint(e.codePointAt(0))
      this.i += cp.length
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) out += map[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail('invalid escape \\' + cp)
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const r = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return r
  }
  name() {
    const c = this.c
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (isNameCh(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c !== '.') { this.i = save; return parts }
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }

  value() {
    this.ws()
    const c = this.c
    if (this.atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { type: 'string', value: this.basic() }
    if (c === "'") return { type: 'string', value: this.literal() }
    if (c === '[') return this.array()
    if (c === '{') return this.inline()
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && !',]}'.includes(this.c)) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { type: 'boolean', value: w === 'true' }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { type: 'integer', value: Number(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(w)) {
      return { type: 'float', value: Number(w.replace(/_/g, '')) }
    }
    fail('invalid value ' + w)
  }
  array() {
    this.i++
    const a = { type: 'array', items: [], tables: false }
    this.ws()
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') { this.i++; return a }
      a.items.push(this.value())
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; return a }
      fail('unterminated array')
    }
  }
  inline() {
    this.i++
    const t = newTable()
    this.ws()
    if (this.c === '}') { this.i++; return t }
    if (this.atEnd()) fail('unterminated inline table')
    for (;;) {
      this.ws()
      const keys = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value()
      assign(t, keys, v, [])
      this.ws()
      if (this.c === ',') { this.i++; this.ws(); continue }
      if (this.c === '}') { this.i++; return t }
      fail('unterminated inline table')
    }
  }
}

// Walk keys through tables from `base`, creating tables; returns the table reached.
function walk(base, keys, prefix, create) {
  let t = base
  const path = [...prefix]
  for (const k of keys) {
    path.push(k)
    let n = t.map.get(k)
    if (!n) { n = newTable(); t.map.set(k, n) }
    if (n.type === 'array' && n.tables) n = n.items[n.items.length - 1]
    if (n.type !== 'table') fail(`${path.join('.')} is not a table`)
    t = n
  }
  return t
}

function assign(cur, keys, v, prefix) {
  const t = walk(cur, keys.slice(0, -1), prefix, true)
  const k = keys[keys.length - 1]
  if (t.map.has(k)) fail(`key ${[...prefix, ...keys].join('.')} is defined twice`)
  t.map.set(k, v)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  lines.forEach((raw, idx) => {
    try {
      const L = new Line(raw)
      L.ws()
      if (L.atEnd()) return
      if (L.c === '[') {
        const isArr = raw[L.i + 1] === '['
        L.i += isArr ? 2 : 1
        L.ws()
        const keys = L.dotted()
        L.ws()
        if (L.c !== ']') fail('unterminated table header')
        L.i++
        if (isArr) {
          if (L.c !== ']') fail('unterminated table header')
          L.i++
        }
        L.ws()
        if (!L.atEnd()) fail('trailing text after a table header')
        const parent = walk(root, keys.slice(0, -1), [], true)
        const k = keys[keys.length - 1]
        const path = keys.join('.')
        const n = parent.map.get(k)
        if (isArr) {
          if (!n) {
            cur = newTable()
            parent.map.set(k, { type: 'array', items: [cur], tables: true })
          } else if (n.type === 'array' && n.tables) {
            cur = newTable()
            n.items.push(cur)
          } else fail(`${path} is not an array of tables`)
        } else if (!n) {
          cur = newTable()
          cur.header = true
          parent.map.set(k, cur)
        } else if (n.type !== 'table') fail(`${path} is not a table`)
        else {
          if (n.header) fail(`table ${path} is defined twice`)
          n.header = true
          cur = n
        }
        return
      }
      const keys = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value()
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, keys, v, [])
    } catch (e) {
      if (e instanceof Fail) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.type === 'table') {
    const ks = [...n.map.keys()].sort(cmp)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.type === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.value)
}

function keysOut(n, path, out) {
  if (n.type === 'table') {
    for (const k of [...n.map.keys()].sort(cmp)) {
      const p = path === null ? k : `${path}.${k}`
      const c = n.map.get(k)
      out.push(`${p} ${c.type}`)
      keysOut(c, p, out)
    }
  } else if (n.type === 'array') {
    n.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${c.type}`)
      keysOut(c, p, out)
    })
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
try {
  const root = parse(readFileSync(0, 'utf8'))
  if (args[0] === 'json') process.stdout.write(toJson(root, 0) + '\n')
  else {
    const out = []
    keysOut(root, null, out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
